import {schemaFor,settingsFor,operators} from './results.js';
import {parameterFields} from './parameters.js';
export const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const options=(values,selected)=>values.map(value=>`<option value="${escape(value)}" ${value===selected?'selected':''}>${escape(value)}</option>`).join('');
export function renderResults(step,action){
  const schema=schemaFor(action,step.values);if(!schema)return '';
  const r=settingsFor(action,step);
  return `<details class="result-controls"><summary>Fields, filters & sorting</summary><fieldset class="field-picker"><legend>Output fields</legend>${schema.fields.map(f=>`<label><input type="checkbox" data-result-field="${f.name}" ${r.fields.includes(f.name)?'checked':''}>${f.name}</label>`).join('')}</fieldset><div class="result-filters">${r.filters.map((filter,index)=>`<div class="result-filter" data-filter-index="${index}"><label class="field">Filter field<select data-filter="field">${options(schema.fields.map(f=>f.name),filter.field)}</select></label><label class="field">Operator<select data-filter="operator">${options(operators(schema.fields.find(f=>f.name===filter.field)?.type||'text'),filter.operator)}</select></label><label class="field">Filter value<input data-filter="value" maxlength="500" value="${escape(filter.value)}" placeholder="${schema.fields.find(f=>f.name===filter.field)?.type==='date'?'Age in days':'Value'}"></label><button data-remove-filter="${index}" class="text-button" aria-label="Remove filter ${index+1}">×</button></div>`).join('')}</div><button data-add-filter class="text-button" ${r.filters.length>=6?'disabled':''}>Add result filter</button><div class="result-sort"><label class="field">Sort by<select data-result="sort"><option value="">Command order</option>${options(schema.fields.map(f=>f.name),r.sort)}</select></label><label class="field check"><input type="checkbox" data-result="descending" ${r.descending?'checked':''}><span>Descending</span></label><label class="field">Result limit<input type="number" data-result="limit" min="0" max="5000" value="${r.limit}"><small>0 means no extra limit.</small></label></div><p class="flags-help">Filters combine with AND and use supported properties only. No PowerShell expressions.</p></details><small class="error" data-results-error></small><details class="sample-results"><summary>Sample output</summary><div data-sample></div></details>`;
}
export function sampleMarkup(step,action){
  const schema=schemaFor(action,step.values);if(!schema)return '';
  const r=settingsFor(action,step),fields=r.fields.filter(name=>schema.fields.some(f=>f.name===name));
  const rows=schema.rows.map(row=>Object.fromEntries(fields.map(name=>[name,row[name]??'—'])));
  const body=step.output?.format==='json'?`<pre>${escape(JSON.stringify(rows,null,2))}</pre>`:step.output?.format==='csv'?`<pre>${escape([fields.join(','),...rows.map(row=>fields.map(name=>'"'+String(row[name]).replaceAll('"','""')+'"').join(','))].join('\n'))}</pre>`:`<div class="sample-table" tabindex="0" aria-label="Illustrative output table"><table><thead><tr>${fields.map(name=>`<th scope="col">${name}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${fields.map(name=>`<td>${escape(row[name])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  return `<strong>Sample output — illustrative data, not executed results</strong>${body}<p>${escape(schema.help)} Sample rows explain the shape of output; filters do not simulate your machine’s data.</p>`;
}
export function renderCondition(step,index,steps){
  const c=step.condition||{type:'none',sourceStep:-1},sources=steps.slice(0,index).map((s,i)=>({s,i})).filter(({s})=>['network','tcp-port'].includes(s.actionId)&&!s.bulk?.field);
  return `<fieldset class="command-flags"><legend>Run condition</legend><label class="field">Run this step<select data-condition="type"><option value="none" ${c.type==='none'?'selected':''}>Always</option>${step.actionId==='restart'?`<option value="service-stopped" ${c.type==='service-stopped'?'selected':''}>Only if the selected service is stopped</option>`:''}<option value="connectivity" ${c.type==='connectivity'?'selected':''}>Only when an earlier connectivity check succeeds</option></select></label>${c.type==='connectivity'?`<label class="field">Earlier check<select data-condition="sourceStep"><option value="-1">Choose a check</option>${sources.map(({s,i})=>`<option value="${i}" ${c.sourceStep===i?'selected':''}>Step ${i+1}: ${escape(s.values.host)} (${s.actionId==='network'?'ping':'TCP'})</option>`).join('')}</select></label>`:''}<p class="flags-help">A false condition skips the step. Execution summaries distinguish Skipped, Failed and Succeeded. Ping/TCP outcomes differ from command execution success.</p><small class="error" data-condition-error></small></fieldset>`;
}
export function renderStepParameters(step,action,workspace){
  if(workspace.exportMode!=='parameters')return '';
  return `<details class="parameter-controls"><summary>Script parameters</summary><p class="flags-help">Promote supported custom text inputs to string parameters. Shared inputs can be promoted in Shared inputs. Required parameters must be supplied when running the script.</p>${parameterFields(action).filter(p=>!step.bindings?.[p.name]&&step.bulk?.field!==p.name).map(p=>{const config=step.parameterFields?.[p.name]||{};return `<fieldset data-parameter-field="${p.name}" class="command-flags"><legend>${escape(p.label)}</legend><label class="field check"><input data-step-parameter="enabled" type="checkbox" ${config.enabled?'checked':''}><span>Export as a parameter</span></label>${config.enabled?`<label class="field">Parameter name<input data-step-parameter="name" value="${escape(config.name)}" maxlength="40"></label><label class="field check"><input data-step-parameter="required" type="checkbox" ${config.required?'checked':''}><span>Required at runtime (no default)</span></label><small>Otherwise the configured value becomes the default.</small>`:''}</fieldset>`;}).join('')}<p class="error" data-parameter-error></p></details>`;
}
